#!/usr/bin/env python3
"""Tiny deterministic, typed MIG-style fixture interface generator (not mig)."""
from pathlib import Path
import sys

SPEC = ((4100, "add", ("lhs", "rhs")), (4200, "multiply", ("lhs", "rhs")))

def generate() -> str:
    lines = [
        "/* generated by tools/phase22e-generate.py; do not edit. */",
        "#ifndef PHASE22E_GENERATED_H", "#define PHASE22E_GENERATED_H",
        '#include "ios27/phase22e_ipc.h"',
        "#include <stdint.h>", "#include <stddef.h>",
        "typedef struct { phase22e_header header; uint32_t sequence; uint32_t lhs; uint32_t rhs; } phase22e_calc_request;",
        "typedef struct { phase22e_header header; uint32_t sequence; uint32_t value; } phase22e_calc_reply;",
        '_Static_assert(sizeof(phase22e_calc_request) == 36, "request wire ABI");',
        '_Static_assert(sizeof(phase22e_calc_reply) == 32, "reply wire ABI");',
    ]
    for mid, name, fields in SPEC:
        assert fields == ("lhs", "rhs")
        lines += [f"#define PHASE22E_ID_{name.upper()} {mid}",
                  f"#define PHASE22E_REPLY_{name.upper()} {mid + 100}"]
    return "\n".join(lines + ["#endif", ""])

if __name__ == "__main__":
    target = Path(__file__).resolve().parent.parent / "tests" / "phase22e-generated.h"
    data = generate()
    if len(sys.argv) == 2 and sys.argv[1] == "--check":
        if not target.is_file() or target.read_text() != data:
            sys.exit("generated interface out of date")
    elif len(sys.argv) == 1:
        target.write_text(data)
    else:
        sys.exit("usage: phase22e-generate.py [--check]")
